self.KB_CONTENT["card:750787"]={"id":"card:750787","ty":"card","sourceId":"750787","title":"『結帳單自動結帳作業』中的『選擇課稅別 (COP.TG017，COP.TI013)』為何？","ver":"iGP","topic":"結帳單","keywords":["結帳單","課稅別","稅率"],"y":"other","answer":"* 區分為1.應稅內含、2.應稅外加、3.零稅率、4.免稅、9.不計稅及A.全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
