self.KB_CONTENT["card:758695"]={"id":"card:758695","ty":"card","sourceId":"758695","title":"『批號結案作業』的作業目的為何？","ver":"iGP","topic":"品號","keywords":["品號","狀態","入庫","結案"],"y":"explain","answer":"針對批號管理件，入庫＝出庫數量者，將該品號「批號資料建立作業」中之『結案碼』狀態改由【未結案】改為【已結案】，或針對狀態碼為【已結案】改為【未結案】。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
