self.KB_CONTENT["card:771777"]={"id":"card:771777","ty":"card","sourceId":"771777","title":"訂單變更單憑證(EPMR54)要顯示單頭的專案名稱，請問欄位代號為何？","ver":"GP4.X","topic":"變更單","keywords":["變更單","憑證","訂單","檢視"],"y":"other","answer":"請進【設計憑證】裡，【元件檢視器】中找“AtxtTE9I1C“勾選列印，即會顯示專案名稱。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
