self.KB_CONTENT["card:755421"]={"id":"card:755421","ty":"card","sourceId":"755421","title":"『批號存貨庫齡分析表(先進先出)』中的『選擇批號結案狀態』為何？","ver":"iGP","topic":"分析表","keywords":["分析表","狀態","結案","批號"],"y":"other","answer":"* 分為N.未結案、Y.已結案及A.全部三種結案狀態。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
