self.KB_CONTENT["card:783268"]={"id":"card:783268","ty":"card","sourceId":"783268","title":"『應付票據交寄大宗郵件憑證』中的『輸入郵資 (N 5.2)』為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","應付","票據"],"y":"other","answer":"* 只可輸入數值，可空白。* 郵資共計=郵資*件數。* 輸入郵資不為空白且不為零時，需列印在郵資欄位中。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
