self.KB_CONTENT["card:779768"]={"id":"card:779768","ty":"card","sourceId":"779768","title":"『委外工單開立』中的『發料類型 (TH045)』為何？","ver":"GP4以上","topic":"品號","keywords":["品號","異動","工單","開立"],"y":"other","answer":"* 分為1.工程品號及2.正式品號兩種類型。* 類型異動清除品號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
