self.KB_CONTENT["field:878924"]={"id":"field:878924","ty":"field","sourceId":"878924","title":"單別","ver":"GP40.iGP 以上","topic":"","keywords":[],"job":"庫存異動單據建立作業","code":"","answer":"可以查看該單別在『單別性質設定作業-INVI04』是否有勾選【單別限定輸入使用者】，但子單身【單別限定輸入使用者】的名單內沒有該名使用者，若是則在『庫存異動單據建立作業-INVI05』會無法使用該單別","file":"fields.jsonl"};
