self.KB_CONTENT["field:793135"]={"id":"field:793135","ty":"field","sourceId":"793135","title":"拋轉傳票排列方式","ver":"GP4以上","topic":"","keywords":[],"job":"產生分錄底稿","code":"","answer":"拋轉傳票排列方式* 分為1.依借貸方及2.依原底稿兩種排列方式。* 預設拋轉傳票排列方式。","file":"fields.jsonl"};
